__NUXT_JSONP__("/por/how-to-apply/student-visa-f1/change-of-status", {data:[{details:{slug:"por",pageTitle:"Mudança de Status | Mentor Language Institute",pageDescription:"Muito obrigado pelo seu interesse em se inscrever na MLI. Esta página é para aqueles que estão atualmente nos EUA, sem um visto de F1 (estudante), e gostariam de mudar para o status de F1.",title:"Mudança de Status",image:"\u002Fimages\u002Fhow-to-apply\u002Fchange-of-status\u002Fchange-of-status.jpg",subtitle:["Muito obrigado pelo seu interesse em se inscrever na MLI.\u003Cbr \u002F\u003EEsta página é para aqueles que estão atualmente nos EUA, sem um visto de F1 (estudante), e gostariam de mudar para o status de F1.","Caso deseje aplicar, clique no botão abaixo:"],applyOnline:{imageLink:{image:"\u002Fimages\u002Fhow-to-apply\u002Fchange-of-status\u002Fapply-now-por.png",link:"\u002Fpor\u002Fadmission"}},applicationSteps:{title:"Etapas da Aplicação",description:["As etapas exatas da inscrição dependem do país, da nacionalidade, do curso, do visto, etc. Nossa equipe terá prazer em orientá-lo em cada etapa com base em sua situação exclusiva."]},needHelp:{title:"Precisa de ajuda? Pergunte para nós!",description:["As regras de visto e as etapas de inscrição são diferentes com base no seu status atual.\u003Cbr \u002F\u003ESe você precisar de esclarecimentos antes de se inscrever, não hesite em nos contatar. Temos uma equipe fluente em até 8 idiomas!"]},contactUs:{image:"\u002Fimages\u002Fhow-to-apply\u002Fchange-of-status\u002Fcontact-us-por.jpg",link:"\u002Fpor\u002Fcontact",title:"Contate-nos",lists:[{campus:"＜WESTWOOD CAMPUS＞",address:"10880 Wilshire Blvd., Suite #122, Los Angeles, CA 90024",telephone:"Tel:310⁻887⁻0777"},{campus:"＜HOLLYWOOD CAMPUS＞",address:"7080 Hollywood Blvd., Suite 314 Los Angeles, CA 90028",telephone:"Tel:323⁻870⁻7102"}]},dir:"\u002Fchange-of-status",path:"\u002Fchange-of-status\u002Fpor",extension:".json",createdAt:"2026-10-22T16:31:28.795Z",updatedAt:"2025-05-26T12:06:27.714Z"}}],fetch:{},mutations:void 0});